-- Guarded cleanup of inert legacy resource child pools, batch 07.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2197,2199,2200,2201,2202,2203,2204,2205,2206,2207,2208,2209,2211,2212,2213,2214,2215,2216,2218,2222,2223,2225,2226,2227,2230,2231,2232,2233,2234,2235,2236,2239,2241,2242,2243,2244,2245,2246,2247,2249,2250,2251,2253,2254,2256,2257,2259,2260,2261,2263) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2197,2199,2200,2201,2202,2203,2204,2205,2206,2207,2208,2209,2211,2212,2213,2214,2215,2216,2218,2222,2223,2225,2226,2227,2230,2231,2232,2233,2234,2235,2236,2239,2241,2242,2243,2244,2245,2246,2247,2249,2250,2251,2253,2254,2256,2257,2259,2260,2261,2263) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

